def esc(v):
    v = v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    v = v.replace("'", "\\'").replace('"', '\\"')
    if v.startswith("@") or v.startswith("?"):
        v = "\\" + v
    return v

out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- Generated by tools/gen_strings.py. Russian is the default locale; add values-xx/strings.xml for other languages. -->', "<resources>"]
for k, v in S.items():
    has_args = re.search(r"%\d\$", v) is not None
    if "%" in v and not has_args:
        out.append(f'    <string name="{k}" formatted="false">{esc(v)}</string>')
    else:
        out.append(f'    <string name="{k}">{esc(v)}</string>')
out.append("</resources>")
path = os.path.join(os.path.dirname(__file__), "..", "app", "src", "main", "res", "values", "strings.xml")
open(path, "w", encoding="utf-8").write("\n".join(out) + "\n")
print(len(S), "strings")
